// Flashcards. Schema: { id, cat, front, back, source, status }. See docs/CONTENT_GUIDE.md.
// Starter set plus batch 2. All 'draft' until reviewed by a licensed RN / nurse educator.
DATA.flashcards = [
  { id: 'fc-moc-001', cat: 'moc', front: 'What can an RN delegate to unlicensed assistive personnel (UAP)?', back: 'Stable, predictable tasks with expected outcomes: hygiene, ambulation, feeding, routine vital signs on stable clients. Not assessment, teaching, evaluation or care of unstable clients.', source: 'Open RN, Nursing Management & Professional Concepts', status: 'draft' },
  { id: 'fc-moc-002', cat: 'moc', front: 'Who obtains informed consent for a procedure?', back: 'The provider performing the procedure explains it and obtains consent. The nurse may witness the signature and confirms the client understood.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-safety-001', cat: 'safety', front: 'Which precautions for tuberculosis, measles and varicella?', back: 'Airborne precautions: N95 respirator (or higher) and an airborne infection isolation (negative-pressure) room.', source: 'CDC Isolation Precautions guideline', status: 'draft' },
  { id: 'fc-safety-002', cat: 'safety', front: 'C. difficile: hand hygiene method?', back: 'Soap and water. Alcohol-based rubs do not reliably kill C. difficile spores. Use contact precautions.', source: 'CDC', status: 'draft' },
  { id: 'fc-safety-003', cat: 'safety', front: 'Fire response acronym', back: 'RACE: Rescue, Alarm, Contain, Extinguish/Evacuate. Fire extinguisher use: PASS (Pull, Aim, Squeeze, Sweep).', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-health-001', cat: 'health', front: 'When does an infant typically sit without support?', back: 'Around 6 months (most by 6–8 months).', source: 'CDC developmental milestones', status: 'draft' },
  { id: 'fc-health-002', cat: 'health', front: 'Normal fetal heart rate range', back: '110–160 beats per minute.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-psych-001', cat: 'psych', front: 'First priority with a client expressing suicidal thoughts', back: 'Safety: ask directly about a plan and means, stay with or keep the client under close observation, and remove hazards.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-002', cat: 'psych', front: 'Therapeutic vs. non-therapeutic: "Why did you do that?"', back: 'Non-therapeutic. "Why" questions can feel accusatory. Use open-ended prompts such as "Tell me more about what happened."', source: 'Open RN, Nursing Mental Health & Community Concepts', status: 'draft' },
  { id: 'fc-basic-001', cat: 'basic', front: 'How often should an immobile client be repositioned?', back: 'At least every 2 hours (more often if at high risk), to prevent pressure injuries.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-002', cat: 'basic', front: 'Cane: which side and how?', back: 'Hold it on the stronger side. Move the cane and weaker leg together, then the stronger leg.', source: 'Open RN, Nursing Fundamentals', status: 'draft' },
  { id: 'fc-pharm-001', cat: 'pharm', front: 'Antidote for heparin', back: 'Protamine sulfate. Monitor aPTT for heparin therapy.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-002', cat: 'pharm', front: 'Antidote for warfarin', back: 'Vitamin K (phytonadione). Monitor PT/INR for warfarin therapy.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-003', cat: 'pharm', front: 'Before giving digoxin, check…', back: 'Apical pulse for a full minute; hold and report if below 60/min in adults (or as ordered). Watch potassium: low K+ raises toxicity risk.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-004', cat: 'pharm', front: 'Rights of medication administration (core 6)', back: 'Right client, drug, dose, route, time and documentation.', source: 'Open RN, Nursing Pharmacology', status: 'draft' },
  { id: 'fc-risk-001', cat: 'risk', front: 'Normal serum potassium', back: 'About 3.5–5.0 mEq/L (ranges vary slightly by lab).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-002', cat: 'risk', front: 'Allen test is done before…', back: 'Radial artery puncture or arterial line placement, to confirm ulnar collateral circulation.', source: 'Open RN, Nursing Advanced Skills', status: 'draft' },
  { id: 'fc-adapt-001', cat: 'adapt', front: 'Classic signs of hypoglycemia', back: 'Shakiness, sweating, tachycardia, confusion, irritability. If alert: give 15 g fast-acting carbohydrate and recheck in 15 minutes.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-002', cat: 'adapt', front: 'Cushing triad suggests…', back: 'Rising intracranial pressure: hypertension with widening pulse pressure, bradycardia, irregular respirations.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-003', cat: 'adapt', front: 'Left- vs right-sided heart failure', back: 'Left: backs up into the lungs (crackles, dyspnea, pink frothy sputum). Right: backs up into the body (JVD, dependent edema, hepatomegaly).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  // Batch 2 (Nov 2026): original drafts written from open sources, pending RN review.
  { id: 'fc-moc-003', cat: 'moc', front: 'Five rights of delegation', back: 'Right task, right circumstance, right person, right directions and communication, right supervision and evaluation.', source: 'NCSBN, NCLEX-RN Test Plan and delegation guidelines', status: 'draft' },
  { id: 'fc-moc-004', cat: 'moc', front: 'Can an LPN/LVN do the initial assessment of a newly admitted client?', back: 'No. The RN does the initial assessment, care planning and evaluation. LPN/LVNs collect data and reinforce teaching for stable clients.', source: 'NCSBN, NCLEX-RN Test Plan and delegation guidelines', status: 'draft' },
  { id: 'fc-moc-005', cat: 'moc', front: 'Which client should the nurse see first after shift report?', back: 'Use ABCs, then acute over chronic, unstable over stable, and actual over potential problems. An airway or breathing problem usually comes first.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-006', cat: 'moc', front: 'Maslow priority order', back: 'Physiological needs first, then safety, then love and belonging, then esteem, then self-actualization.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-007', cat: 'moc', front: 'SBAR stands for…', back: 'Situation, Background, Assessment, Recommendation: a structured way to hand off or report to a provider.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-008', cat: 'moc', front: 'Who can witness informed consent?', back: 'A nurse or other adult can witness the signature. The witness confirms the client signed voluntarily, not that the client understands the procedure details (that is the provider\'s job).', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-009', cat: 'moc', front: 'Client has questions after signing consent. What does the nurse do?', back: 'Hold the procedure and notify the provider, who must answer the questions. Consent must be informed.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-010', cat: 'moc', front: 'Can a client refuse treatment after signing consent?', back: 'Yes. Consent can be withdrawn at any time. Stop, document and notify the provider.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-011', cat: 'moc', front: 'Emancipated minor', back: 'A minor who is legally treated as an adult (for example married, in the military or court-emancipated) and can consent to their own care.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-012', cat: 'moc', front: 'HIPAA: may the nurse discuss a client with a friend calling the unit?', back: 'No, not without the client\'s permission. Share information only with people directly involved in care or authorized by the client.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-013', cat: 'moc', front: 'Advance directive', back: 'A legal document stating a client\'s wishes for future care, such as a living will or a durable power of attorney for health care.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-014', cat: 'moc', front: 'Health care proxy (durable power of attorney for health care)', back: 'A person the client names to make health care decisions when the client cannot.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-015', cat: 'moc', front: 'Do-not-resuscitate (DNR) order means…', back: 'No CPR if the heart or breathing stops. It does not mean withholding other care such as pain relief, fluids or antibiotics unless ordered.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-016', cat: 'moc', front: 'Incident (occurrence) report: where does it go?', back: 'To risk management. It is not placed in the medical record and is not mentioned in charting.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-017', cat: 'moc', front: 'Negligence vs. malpractice', back: 'Negligence: failing to give the care a reasonable person would. Malpractice: professional negligence by a licensed person that causes harm.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-018', cat: 'moc', front: 'Four elements needed to prove malpractice', back: 'Duty, breach of duty, causation and damages (harm).', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-019', cat: 'moc', front: 'Assault vs. battery', back: 'Assault: a threat that makes someone fear being touched. Battery: touching someone without consent.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-020', cat: 'moc', front: 'False imprisonment in health care', back: 'Restraining or confining a client without a legal order or valid reason, including using restraints for staff convenience.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-021', cat: 'moc', front: 'Restraint order basics', back: 'Needs a provider order (never PRN). Use the least restrictive option, check the client often, and release, reposition and assess circulation regularly per policy.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-022', cat: 'moc', front: 'Tying restraints to the bed', back: 'Tie to the bed frame (the part that moves with the client), never the side rails. Use a quick-release knot.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-moc-023', cat: 'moc', front: 'Client wants to leave against medical advice (AMA)', back: 'Explain the risks, notify the provider, ask the client to sign the AMA form and document. An adult with capacity cannot be held against their will.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-024', cat: 'moc', front: 'Nurse receives an unclear or unsafe order. Action?', back: 'Clarify with the prescriber before carrying it out. If still unsafe, follow the chain of command.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-025', cat: 'moc', front: 'Verbal or telephone orders', back: 'Write the order down and read it back to confirm. The prescriber co-signs within the time set by policy.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-026', cat: 'moc', front: 'Chain of command', back: 'Report a concern up the hierarchy: charge nurse, then nurse manager, then supervisor or medical director, when a problem is not resolved.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-027', cat: 'moc', front: 'Mandatory reporting duties of the nurse', back: 'Suspected child or elder abuse, certain communicable diseases, and gunshot or knife wounds (per state law).', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-028', cat: 'moc', front: 'Triage in a mass casualty event: red, yellow, green, black', back: 'Red: immediate, life-threatening but survivable. Yellow: delayed, serious but stable. Green: minor ("walking wounded"). Black: deceased or not expected to survive.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-029', cat: 'moc', front: 'What can an RN assign to an LPN/LVN?', back: 'Care of stable clients with predictable outcomes, including most oral, IM and subcutaneous medications and data collection, within state scope.', source: 'NCSBN, NCLEX-RN Test Plan and delegation guidelines', status: 'draft' },
  { id: 'fc-moc-030', cat: 'moc', front: 'Tasks the RN should not delegate to UAP', back: 'Assessment, client teaching, evaluation, care planning, and care of unstable clients.', source: 'NCSBN, NCLEX-RN Test Plan and delegation guidelines', status: 'draft' },
  { id: 'fc-moc-031', cat: 'moc', front: 'Ethical principle: autonomy', back: 'Respecting the client\'s right to make their own decisions, even ones the nurse disagrees with.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-032', cat: 'moc', front: 'Beneficence vs. nonmaleficence', back: 'Beneficence: doing good for the client. Nonmaleficence: avoiding harm.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-033', cat: 'moc', front: 'Justice and fidelity (ethics)', back: 'Justice: fair distribution of care. Fidelity: keeping promises and commitments to clients.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-034', cat: 'moc', front: 'Using an interpreter', back: 'Use a trained medical interpreter, not family members. Speak directly to the client, not the interpreter.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-035', cat: 'moc', front: 'Discharge planning starts when?', back: 'At admission.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-moc-036', cat: 'moc', front: 'Continuous quality improvement (CQI)', back: 'An ongoing process of measuring care, finding problems and making system changes to improve outcomes.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-037', cat: 'moc', front: 'Case management', back: 'Coordinating care across settings and providers so the client gets needed services efficiently.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-moc-038', cat: 'moc', front: 'Good Samaritan laws', back: 'Protect people who give emergency help in good faith, within their training, without pay, from liability for ordinary negligence.', source: 'Open RN, Nursing Management and Professional Concepts', status: 'draft' },
  { id: 'fc-safety-004', cat: 'safety', front: 'Diseases needing droplet precautions', back: 'Influenza, pertussis, mumps, rubella, bacterial meningitis (Neisseria meningitidis), and Mycoplasma pneumonia. Surgical mask within close range.', source: 'CDC Isolation Precautions guideline', status: 'draft' },
  { id: 'fc-safety-005', cat: 'safety', front: 'Diseases needing contact precautions', back: 'MRSA, VRE, C. difficile, scabies, lice, RSV, and draining wounds. Gown and gloves; dedicated equipment.', source: 'CDC Isolation Precautions guideline', status: 'draft' },
  { id: 'fc-safety-006', cat: 'safety', front: 'Order for putting on PPE', back: 'Gown, mask or respirator, goggles or face shield, then gloves.', source: 'CDC', status: 'draft' },
  { id: 'fc-safety-007', cat: 'safety', front: 'Order for removing PPE', back: 'Gloves, goggles or face shield, gown, then mask or respirator (remove outside the room). Perform hand hygiene.', source: 'CDC', status: 'draft' },
  { id: 'fc-safety-008', cat: 'safety', front: 'Neutropenic (protective) precautions', back: 'Private room, strict hand hygiene, no fresh flowers or plants, avoid raw fruits and vegetables if per policy, and keep sick visitors away.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-safety-009', cat: 'safety', front: 'Fall risk: key interventions', back: 'Bed in low position and locked, call light in reach, non-skid socks, clear pathways, regular toileting, bed alarm if needed.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-safety-010', cat: 'safety', front: 'Two client identifiers', back: 'Use two, such as full name and date of birth. Never use the room number.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-safety-011', cat: 'safety', front: 'Seizure precautions', back: 'Padded side rails, bed low, suction and oxygen at the bedside. Never put anything in the mouth during a seizure.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-safety-012', cat: 'safety', front: 'During a seizure, the nurse should…', back: 'Protect the head, turn the client to the side, loosen tight clothing, time the seizure and stay with the client. Do not restrain.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-safety-013', cat: 'safety', front: 'Sealed radiation implant: key safety rules', back: 'Private room, limit time near the client, use distance and shielding, no pregnant visitors or staff, and keep a lead container and long forceps in the room.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-safety-014', cat: 'safety', front: 'Time, distance, shielding', back: 'The three ways to reduce radiation exposure: spend less time near the source, stay farther away, and use shielding.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-safety-015', cat: 'safety', front: 'Sharps safety', back: 'Never recap used needles. Dispose immediately in a puncture-resistant sharps container.', source: 'CDC', status: 'draft' },
  { id: 'fc-safety-016', cat: 'safety', front: 'Needlestick injury: first action', back: 'Wash the site with soap and water right away, then report it and follow the facility\'s exposure protocol.', source: 'CDC', status: 'draft' },
  { id: 'fc-safety-017', cat: 'safety', front: 'Latex allergy: foods that may cross-react', back: 'Banana, avocado, kiwi and chestnut.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-safety-018', cat: 'safety', front: 'Surgical asepsis: what is sterile on a sterile field?', back: 'Only the top surface inside the 1-inch border. Anything below waist level or out of sight is considered contaminated.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-safety-019', cat: 'safety', front: 'Medical asepsis: how long to wash hands with soap and water?', back: 'At least 20 seconds of scrubbing.', source: 'CDC', status: 'draft' },
  { id: 'fc-safety-020', cat: 'safety', front: 'Contact precautions: equipment', back: 'Use dedicated equipment (stethoscope, BP cuff) that stays in the room, or clean it thoroughly before using it on another client.', source: 'CDC Isolation Precautions guideline', status: 'draft' },
  { id: 'fc-safety-021', cat: 'safety', front: 'Airborne precautions room requirement', back: 'An airborne infection isolation room with negative pressure and the door kept closed.', source: 'CDC Isolation Precautions guideline', status: 'draft' },
  { id: 'fc-safety-022', cat: 'safety', front: 'Hazardous chemical exposure information source', back: 'The Safety Data Sheet (SDS) for the product.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-safety-023', cat: 'safety', front: 'Electrical equipment safety', back: 'Do not use frayed cords or ungrounded plugs. Remove damaged equipment from use and report it.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-safety-024', cat: 'safety', front: 'Order to evacuate clients in a fire', back: 'Move clients in immediate danger first, then ambulatory clients, then those needing help, and bedbound clients last (per facility plan).', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-safety-025', cat: 'safety', front: 'Herpes zoster (shingles) precautions', back: 'Localized in a healthy client: standard precautions with the lesions covered. Disseminated, or in an immunocompromised client: airborne plus contact precautions.', source: 'CDC Isolation Precautions guideline', status: 'draft' },
  { id: 'fc-safety-026', cat: 'safety', front: 'MRSA treatment drug commonly used IV', back: 'Vancomycin.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-safety-027', cat: 'safety', front: 'Bed rails as restraints', back: 'Four raised side rails can count as a restraint. Follow facility policy; usually only the top two are raised.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-safety-028', cat: 'safety', front: 'Child-safe car seat basics', back: 'Rear-facing for as long as possible, until the child reaches the seat\'s height or weight limit (at least to age 2). Back seat for children under 13.', source: 'American Academy of Pediatrics', status: 'draft' },
  { id: 'fc-health-003', cat: 'health', front: 'Naegele rule for estimating due date', back: 'First day of the last menstrual period, minus 3 months, plus 7 days (plus 1 year).', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-004', cat: 'health', front: 'GTPAL stands for…', back: 'Gravida, Term births, Preterm births, Abortions/miscarriages, Living children.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-005', cat: 'health', front: 'Normal APGAR timing and meaning', back: 'Scored at 1 and 5 minutes on heart rate, breathing, muscle tone, reflex irritability and color. 7–10 is reassuring.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-006', cat: 'health', front: 'Normal newborn heart and breathing rates', back: 'Heart rate about 110–160 bpm. Respiratory rate about 30–60 breaths per minute.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-007', cat: 'health', front: 'Vitamin K for the newborn: why?', back: 'Newborns lack gut bacteria to make vitamin K, so a single IM dose prevents bleeding (vitamin K deficiency bleeding).', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-008', cat: 'health', front: 'Eye ointment for the newborn', back: 'Erythromycin ointment to prevent gonococcal eye infection.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-009', cat: 'health', front: 'Early decelerations on a fetal monitor', back: 'Mirror contractions and are caused by head compression. Usually benign: no action needed.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-010', cat: 'health', front: 'Late decelerations: cause and actions', back: 'Uteroplacental insufficiency. Turn the client to the side, stop oxytocin, give IV fluids and oxygen per protocol, and notify the provider.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-011', cat: 'health', front: 'Variable decelerations: cause and first action', back: 'Cord compression. Reposition the client; check for cord prolapse if sudden.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-012', cat: 'health', front: 'VEAL CHOP mnemonic', back: 'Variable = Cord compression; Early = Head compression; Accelerations = OK; Late = Placental insufficiency.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-013', cat: 'health', front: 'Prolapsed umbilical cord: nurse actions', back: 'Call for help, lift the presenting part off the cord with a gloved hand, place the client in knee-chest or Trendelenburg position, and prepare for urgent delivery. Do not push the cord back.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-014', cat: 'health', front: 'Postpartum fundus: what is normal?', back: 'Firm and midline, at the umbilicus right after birth, then dropping about 1 cm (one fingerbreadth) per day.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-015', cat: 'health', front: 'Boggy uterus after birth: first action', back: 'Massage the fundus until firm, then check bleeding and help the client empty the bladder.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-016', cat: 'health', front: 'Lochia order', back: 'Rubra (red, days 1–3), serosa (pink-brown, about days 4–10), alba (white-yellow, up to about 6 weeks).', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-017', cat: 'health', front: 'Rh immune globulin: who and when?', back: 'Rh-negative client with an Rh-positive (or unknown) baby: given around 28 weeks of pregnancy and within 72 hours after birth.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-018', cat: 'health', front: 'When does an infant typically roll over?', back: 'Around 4–6 months.', source: 'CDC developmental milestones', status: 'draft' },
  { id: 'fc-health-019', cat: 'health', front: 'When does a child typically walk alone?', back: 'Around 12–15 months.', source: 'CDC developmental milestones', status: 'draft' },
  { id: 'fc-health-020', cat: 'health', front: 'Birth weight: when does it double and triple?', back: 'Doubles by about 5–6 months and triples by about 12 months.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-health-021', cat: 'health', front: 'Erikson stage for toddlers', back: 'Autonomy vs. shame and doubt. Let toddlers make simple choices.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-health-022', cat: 'health', front: 'Erikson stage for adolescents', back: 'Identity vs. role confusion. Peers matter most; respect privacy.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-health-023', cat: 'health', front: 'Breast cancer screening (general guidance)', back: 'Mammograms for average-risk women are commonly recommended every 1–2 years starting at age 40 to 50, depending on the guideline.', source: 'OpenStax, Population Health for Nurses', status: 'draft' },
  { id: 'fc-health-024', cat: 'health', front: 'Colorectal cancer screening start age (average risk)', back: 'Age 45.', source: 'OpenStax, Population Health for Nurses', status: 'draft' },
  { id: 'fc-health-025', cat: 'health', front: 'Live vaccines to avoid in pregnancy', back: 'MMR and varicella. Give them before pregnancy or after birth.', source: 'CDC immunization schedules', status: 'draft' },
  { id: 'fc-health-026', cat: 'health', front: 'Teaching about testicular self-exam', back: 'Monthly, during or after a warm shower, rolling each testicle gently between the fingers to feel for lumps.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-psych-003', cat: 'psych', front: 'Therapeutic technique: open-ended question', back: 'Invites the client to share more, e.g. "Tell me about how you\'ve been feeling." Avoid yes/no questions.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-004', cat: 'psych', front: 'Non-therapeutic: false reassurance', back: 'Saying things like "Everything will be fine" dismisses the client\'s feelings and blocks communication.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-005', cat: 'psych', front: 'Hallucinations: best nurse response', back: 'Acknowledge the client\'s experience, present reality calmly ("I don\'t hear the voices, but I know they are real to you"), and keep the client safe. Do not argue.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-006', cat: 'psych', front: 'Delusions: how to respond', back: 'Do not argue or agree. Focus on the feelings behind the delusion and redirect to reality-based topics.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-007', cat: 'psych', front: 'Alcohol withdrawal: when do symptoms start?', back: 'Often within 6–24 hours of the last drink. Delirium tremens can appear around 48–72 hours.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-008', cat: 'psych', front: 'Alcohol withdrawal: drug class used', back: 'Benzodiazepines (for example lorazepam or chlordiazepoxide), plus thiamine.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-009', cat: 'psych', front: 'Why give thiamine to clients with alcohol use disorder?', back: 'To prevent Wernicke encephalopathy (confusion, ataxia, eye movement problems).', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-010', cat: 'psych', front: 'Opioid overdose signs', back: 'Pinpoint pupils, slow or stopped breathing, and decreased level of consciousness. Treat with naloxone.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-011', cat: 'psych', front: 'Neuroleptic malignant syndrome signs', back: 'High fever, severe muscle rigidity, altered mental status and unstable vital signs after an antipsychotic. A medical emergency: stop the drug.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-012', cat: 'psych', front: 'Serotonin syndrome signs', back: 'Agitation, fever, sweating, tremor, muscle twitching (hyperreflexia) and diarrhea, often after combining serotonergic drugs.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-013', cat: 'psych', front: 'Escalating, agitated client: first approach', back: 'Stay calm, use a low voice, give space, remove triggers and offer choices. Use restraints or seclusion only as a last resort.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-014', cat: 'psych', front: 'Defense mechanism: displacement', back: 'Moving feelings from the real target to a safer one, e.g. yelling at a nurse after being angry at a provider.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-015', cat: 'psych', front: 'Defense mechanism: projection', back: 'Attributing your own unacceptable feelings to someone else.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-016', cat: 'psych', front: 'Defense mechanism: denial', back: 'Refusing to accept a painful reality, common early in grief or a new diagnosis.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-017', cat: 'psych', front: 'Stages of grief (Kübler-Ross)', back: 'Denial, anger, bargaining, depression, acceptance. People may move between them in any order.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-018', cat: 'psych', front: 'Anorexia nervosa: priority concern', back: 'Physical stability: electrolytes (especially potassium), heart rhythm, and nutrition. Watch for refeeding syndrome when feeding restarts.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-019', cat: 'psych', front: 'Signs of possible child abuse', back: 'Injuries that don\'t match the story, bruises in different healing stages, patterned burns, and delays in seeking care.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-020', cat: 'psych', front: 'Client with depression suddenly seems calm and happy', back: 'This can signal a decision to attempt suicide. Assess suicide risk right away.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-021', cat: 'psych', front: 'Mania: nursing approach', back: 'Low-stimulation environment, high-calorie finger foods, firm and consistent limits, and short, simple communication.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-psych-022', cat: 'psych', front: 'Panic attack: nurse response', back: 'Stay with the client, speak calmly in short sentences, and guide slow breathing. Do not try teaching during the attack.', source: 'OpenStax, Psychiatric-Mental Health Nursing', status: 'draft' },
  { id: 'fc-basic-003', cat: 'basic', front: 'Pressure injury stages 1–4', back: 'Stage 1: intact skin, redness that doesn\'t blanch. Stage 2: partial-thickness loss, shallow open area or blister. Stage 3: full-thickness loss, fat may show. Stage 4: bone, tendon or muscle exposed.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-004', cat: 'basic', front: 'Walker use', back: 'Move the walker forward about one step, then step into it with the weaker leg first, then the stronger leg.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-005', cat: 'basic', front: 'Crutch stairs mnemonic', back: '"Up with the good, down with the bad": going up, lead with the strong leg; going down, lead with the crutches and weak leg.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-006', cat: 'basic', front: 'Correct crutch fit', back: 'Two to three finger widths between the armpit and the crutch pad. Weight goes on the hands, not the armpits.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-007', cat: 'basic', front: 'Position for a client receiving a tube feeding', back: 'Head of bed at least 30–45 degrees during the feeding and for about an hour after, to prevent aspiration.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-basic-008', cat: 'basic', front: 'Dysphagia: safe eating tips', back: 'Sit fully upright, use thickened liquids if ordered, take small bites, and tuck the chin when swallowing.', source: 'OpenStax, Nutrition for Nurses', status: 'draft' },
  { id: 'fc-basic-009', cat: 'basic', front: 'Enema position', back: 'Left side-lying (Sims) position, which follows the natural curve of the colon.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-basic-010', cat: 'basic', front: 'Non-drug pain relief examples', back: 'Repositioning, heat or cold, massage, distraction, music, guided imagery and relaxation breathing.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-011', cat: 'basic', front: 'Reassess pain after an IV opioid', back: 'Typically within about 15–30 minutes. After an oral dose, about 30–60 minutes.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-012', cat: 'basic', front: 'Foods high in potassium', back: 'Bananas, oranges, potatoes, tomatoes, spinach, avocado and dried fruit.', source: 'OpenStax, Nutrition for Nurses', status: 'draft' },
  { id: 'fc-basic-013', cat: 'basic', front: 'Foods high in iron', back: 'Red meat, liver, beans, lentils, spinach and iron-fortified cereal. Vitamin C helps absorption.', source: 'OpenStax, Nutrition for Nurses', status: 'draft' },
  { id: 'fc-basic-014', cat: 'basic', front: 'Low-sodium diet: foods to limit', back: 'Processed and canned foods, deli meats, pickles, cheese, chips and fast food.', source: 'OpenStax, Nutrition for Nurses', status: 'draft' },
  { id: 'fc-basic-015', cat: 'basic', front: 'Clear liquid diet includes…', back: 'Water, broth, clear juices without pulp (apple), gelatin, popsicles and plain tea or coffee. No milk.', source: 'OpenStax, Nutrition for Nurses', status: 'draft' },
  { id: 'fc-basic-016', cat: 'basic', front: 'Postmortem care basics', back: 'Place the body flat with a pillow under the head, close the eyes, insert dentures if possible, and allow family time. Follow policy for tubes and lines.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-017', cat: 'basic', front: 'Signs of approaching death', back: 'Mottled, cool extremities; irregular breathing with pauses (Cheyne-Stokes); noisy secretions; and less urine.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-018', cat: 'basic', front: 'Bladder training for incontinence', back: 'Scheduled voiding at set times, gradually lengthening the interval.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-019', cat: 'basic', front: 'Range-of-motion exercises: active vs. passive', back: 'Active: the client moves the joint. Passive: the nurse moves the joint for the client.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-basic-020', cat: 'basic', front: 'Sleep hygiene tips', back: 'Consistent schedule, limit caffeine and screens before bed, keep the room dark and quiet, and avoid long daytime naps.', source: 'OpenStax, Fundamentals of Nursing', status: 'draft' },
  { id: 'fc-pharm-005', cat: 'pharm', front: 'Antidote for opioid overdose', back: 'Naloxone. Watch for breathing to slow again, because naloxone may wear off before the opioid does.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-006', cat: 'pharm', front: 'Antidote for benzodiazepine overdose', back: 'Flumazenil.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-007', cat: 'pharm', front: 'Antidote for acetaminophen overdose', back: 'Acetylcysteine.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-008', cat: 'pharm', front: 'Antidote for magnesium sulfate toxicity', back: 'Calcium gluconate.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-009', cat: 'pharm', front: 'Magnesium sulfate toxicity signs', back: 'Loss of deep tendon reflexes, respiratory rate below 12, low urine output and decreased level of consciousness.', source: 'OpenStax, Maternal-Newborn Nursing', status: 'draft' },
  { id: 'fc-pharm-010', cat: 'pharm', front: 'Therapeutic digoxin level (typical)', back: 'About 0.5–2.0 ng/mL (many sources use a narrower 0.5–0.9 for heart failure).', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-011', cat: 'pharm', front: 'Early signs of digoxin toxicity', back: 'Nausea, vomiting, loss of appetite, and visual changes such as yellow-green halos. Low potassium increases the risk.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-012', cat: 'pharm', front: 'Lithium therapeutic range (typical)', back: 'About 0.6–1.2 mEq/L. Toxicity above about 1.5.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-013', cat: 'pharm', front: 'Lithium teaching', back: 'Keep salt and fluid intake steady, drink plenty of water, and get regular blood levels. Dehydration or low sodium raises lithium levels.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-014', cat: 'pharm', front: 'Warfarin monitoring lab', back: 'INR (typical target 2–3 for most conditions).', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-015', cat: 'pharm', front: 'Heparin monitoring lab', back: 'aPTT (for IV unfractionated heparin).', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-016', cat: 'pharm', front: 'Warfarin and diet', back: 'Keep vitamin K intake (leafy greens) consistent rather than avoiding it.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-017', cat: 'pharm', front: 'Enoxaparin injection technique', back: 'Subcutaneous in the abdomen, at least 2 inches from the navel. Don\'t expel the air bubble from a prefilled syringe and don\'t rub the site.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-018', cat: 'pharm', front: 'ACE inhibitors: common side effects', back: 'Dry cough, high potassium, and angioedema (swelling of the face or tongue, an emergency). Names end in "-pril".', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-019', cat: 'pharm', front: 'Beta blockers: what to check before giving', back: 'Heart rate and blood pressure. Hold for a low pulse or BP per parameters. Names end in "-olol".', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-020', cat: 'pharm', front: 'Furosemide: key concerns', back: 'Low potassium, dehydration and hypotension. Give in the morning. High IV doses given fast can affect hearing.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-021', cat: 'pharm', front: 'Spironolactone: key concern', back: 'High potassium (it is potassium-sparing). Avoid salt substitutes containing potassium.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-022', cat: 'pharm', front: 'Statins: teaching', back: 'Report unexplained muscle pain (rhabdomyolysis risk). Monitor liver tests. Avoid large amounts of grapefruit juice with some statins.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-023', cat: 'pharm', front: 'Nitroglycerin sublingual for chest pain', back: 'One tablet every 5 minutes, up to 3 doses. Call emergency services if pain is not better 5 minutes after the first dose. Causes headache and low BP.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-024', cat: 'pharm', front: 'Nitrates and erectile dysfunction drugs', back: 'Never take together: dangerous drop in blood pressure.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-025', cat: 'pharm', front: 'Rapid-acting insulin (lispro, aspart) timing', back: 'Onset about 15 minutes. Give with meals, within 15 minutes of eating.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-026', cat: 'pharm', front: 'Regular insulin timing', back: 'Onset about 30–60 minutes, peak 2–4 hours. The only insulin given IV.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-027', cat: 'pharm', front: 'Long-acting insulin (glargine, detemir)', back: 'No real peak, lasts about 24 hours. Do not mix with other insulins.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-028', cat: 'pharm', front: 'Mixing regular and NPH insulin', back: 'Draw up clear (regular) before cloudy (NPH).', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-029', cat: 'pharm', front: 'Metformin: hold before…', back: 'IV contrast studies (risk of lactic acidosis with kidney injury). Restart once kidney function is confirmed per protocol.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-030', cat: 'pharm', front: 'Levothyroxine teaching', back: 'Take on an empty stomach in the morning, 30–60 minutes before breakfast. Lifelong therapy. Report a racing heart or heat intolerance.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-031', cat: 'pharm', front: 'Corticosteroids (prednisone): long-term effects', back: 'High blood sugar, infection risk, bone loss, weight gain and mood changes. Don\'t stop suddenly: taper.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-032', cat: 'pharm', front: 'Phenytoin: key teaching', back: 'Good oral hygiene (gum overgrowth), regular blood levels (typical 10–20 mcg/mL), and avoid alcohol.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-033', cat: 'pharm', front: 'Aminoglycosides (gentamicin) toxicities', back: 'Kidney damage and hearing loss. Monitor peak and trough levels.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-034', cat: 'pharm', front: 'Vancomycin infusion reaction', back: 'Flushing and rash of the upper body ("vancomycin infusion reaction") from infusing too fast. Infuse over at least 60 minutes.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-035', cat: 'pharm', front: 'Fluoroquinolones (ciprofloxacin): warning', back: 'Risk of tendon rupture, especially in older adults or those on steroids.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-036', cat: 'pharm', front: 'Tetracyclines: teaching', back: 'Avoid in pregnancy and young children (tooth staining). Avoid dairy and antacids near the dose. Causes sun sensitivity.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-037', cat: 'pharm', front: 'Metronidazole and alcohol', back: 'Avoid alcohol during treatment and for a few days after: can cause severe nausea and vomiting.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-038', cat: 'pharm', front: 'Isoniazid (TB drug): monitor for…', back: 'Liver damage and peripheral neuropathy. Vitamin B6 (pyridoxine) helps prevent neuropathy.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-039', cat: 'pharm', front: 'Rifampin: harmless side effect to warn about', back: 'Orange-red urine, sweat and tears (can stain contact lenses).', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-040', cat: 'pharm', front: 'Potassium chloride IV safety', back: 'Never give IV push. Always diluted and infused slowly via pump.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-041', cat: 'pharm', front: 'Clozapine: key lab', back: 'White blood cell / absolute neutrophil count, because of the risk of agranulocytosis.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-042', cat: 'pharm', front: 'MAOI dietary restriction', back: 'Avoid tyramine-rich foods (aged cheese, cured meats, tap beer, soy sauce): risk of hypertensive crisis.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-043', cat: 'pharm', front: 'SSRIs: when do they start working?', back: 'Mood improvement often takes 2–6 weeks. Watch for increased suicidal thoughts early on, especially in young people.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-044', cat: 'pharm', front: 'Anticholinergic side effects', back: '"Can\'t see, can\'t pee, can\'t spit, can\'t poop": blurred vision, urinary retention, dry mouth and constipation.', source: 'OpenStax, Pharmacology for Nurses', status: 'draft' },
  { id: 'fc-pharm-045', cat: 'pharm', front: 'IV infiltration vs. phlebitis', back: 'Infiltration: cool, pale, swollen site (fluid in tissue). Phlebitis: warm, red, tender along the vein. Stop the IV in both cases.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-pharm-046', cat: 'pharm', front: 'Blood transfusion: when are reactions most likely?', back: 'In the first 15 minutes. Stay with the client and take vital signs before, at 15 minutes, and per policy.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-pharm-047', cat: 'pharm', front: 'Transfusion reaction: first action', back: 'Stop the transfusion, keep the IV open with normal saline using new tubing, and notify the provider and blood bank.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-pharm-048', cat: 'pharm', front: 'Only fluid compatible with blood products', back: '0.9% sodium chloride (normal saline).', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-pharm-049', cat: 'pharm', front: 'Z-track injection: purpose', back: 'Seals medication in the muscle to prevent leakage and skin staining (for example iron dextran).', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-pharm-050', cat: 'pharm', front: 'Total parenteral nutrition (TPN): key checks', back: 'Blood glucose monitoring, central line care, and never stopping suddenly (rebound low blood sugar).', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-risk-003', cat: 'risk', front: 'Normal serum sodium (typical adult)', back: '135–145 mEq/L.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-004', cat: 'risk', front: 'Normal serum calcium (typical adult total)', back: 'About 8.5–10.5 mg/dL.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-005', cat: 'risk', front: 'Normal serum magnesium (typical adult)', back: 'About 1.5–2.5 mEq/L (1.7–2.2 mg/dL).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-006', cat: 'risk', front: 'Normal fasting blood glucose', back: 'About 70–99 mg/dL.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-007', cat: 'risk', front: 'Hemoglobin A1C targets', back: 'Normal below 5.7%. Diabetes 6.5% or higher. A common treatment goal is below 7%.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-008', cat: 'risk', front: 'Normal BUN and creatinine (typical adult)', back: 'BUN about 7–20 mg/dL. Creatinine about 0.6–1.2 mg/dL.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-009', cat: 'risk', front: 'Normal platelet count', back: 'About 150,000–400,000/mm³. Bleeding precautions below about 50,000.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-010', cat: 'risk', front: 'Normal white blood cell count', back: 'About 5,000–10,000/mm³.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-011', cat: 'risk', front: 'Normal hemoglobin (typical adult)', back: 'Males about 14–18 g/dL; females about 12–16 g/dL.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-012', cat: 'risk', front: 'Normal arterial blood gas values', back: 'pH 7.35–7.45, PaCO2 35–45 mmHg, HCO3 22–26 mEq/L, PaO2 80–100 mmHg.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-013', cat: 'risk', front: 'ROME for ABGs', back: 'Respiratory Opposite (pH and CO2 move in opposite directions), Metabolic Equal (pH and HCO3 move in the same direction).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-014', cat: 'risk', front: 'Hypokalemia ECG change', back: 'Flattened T waves and a U wave.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-015', cat: 'risk', front: 'Hyperkalemia ECG change', back: 'Tall, peaked T waves; can progress to wide QRS and dangerous rhythms.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-016', cat: 'risk', front: 'Signs of low calcium', back: 'Tingling around the mouth, muscle cramps, positive Chvostek and Trousseau signs.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-017', cat: 'risk', front: 'Before a procedure with iodine contrast, ask about…', back: 'Allergies to contrast, kidney function, and metformin use.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-018', cat: 'risk', front: 'After cardiac catheterization (femoral site)', back: 'Keep the leg straight for the ordered time, check the site for bleeding, and check pulses, color and warmth below the site.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-019', cat: 'risk', front: 'After a thyroidectomy: emergency to watch for', back: 'Airway swelling and low calcium (tingling, spasm). Keep a tracheostomy tray at the bedside.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-020', cat: 'risk', front: 'Signs of postoperative bleeding / shock', back: 'Rising heart rate, falling BP, cool clammy skin, restlessness and low urine output.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-021', cat: 'risk', front: 'Minimum adequate urine output (adult)', back: 'About 30 mL per hour (0.5 mL/kg/hour).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-022', cat: 'risk', front: 'Incentive spirometer teaching', back: 'Sit up, seal lips around the mouthpiece, breathe in slowly and deeply, hold 3–5 seconds. About 10 times per hour while awake.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-risk-023', cat: 'risk', front: 'Preventing deep vein thrombosis after surgery', back: 'Early walking, leg exercises, compression devices and anticoagulants as ordered.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-024', cat: 'risk', front: 'Wound dehiscence/evisceration: first action', back: 'Cover the wound with sterile saline-moistened dressing, position with knees bent, stay with the client and call the surgeon.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-025', cat: 'risk', front: 'NG tube placement: best confirmation', back: 'X-ray confirmation, especially before the first feeding. Checking aspirate pH (often 5 or less) supports it.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-risk-026', cat: 'risk', front: 'Suctioning a tracheostomy: key rules', back: 'Pre-oxygenate, use sterile technique, apply suction only while withdrawing, and limit each pass to 10–15 seconds.', source: 'OpenStax, Clinical Nursing Skills', status: 'draft' },
  { id: 'fc-risk-027', cat: 'risk', front: 'Chest tube: continuous bubbling in the water seal chamber', back: 'Suggests an air leak. Check the system from the client to the drainage unit.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-028', cat: 'risk', front: 'Chest tube disconnected from drainage', back: 'Place the end of the tube in sterile water to restore the water seal, and notify the provider.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-risk-029', cat: 'risk', front: 'Signs of hypovolemia', back: 'Fast weak pulse, low BP, dry mucous membranes, poor skin turgor and dark, scant urine.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-004', cat: 'adapt', front: 'Diabetic ketoacidosis (DKA) signs', back: 'High blood glucose, ketones, metabolic acidosis, Kussmaul breathing, fruity breath and dehydration.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-005', cat: 'adapt', front: 'DKA treatment priorities', back: 'IV fluids first, then IV regular insulin, with close potassium monitoring and replacement.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-006', cat: 'adapt', front: 'HHS vs. DKA', back: 'HHS (usually type 2): extremely high glucose and severe dehydration with little or no ketosis. DKA (usually type 1): ketones and acidosis.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-007', cat: 'adapt', front: 'Rule of 15 for hypoglycemia', back: 'Give 15 g of fast-acting carbohydrate, recheck glucose in 15 minutes, repeat if still low, then a snack with protein.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-008', cat: 'adapt', front: 'Signs of a stroke (BE FAST)', back: 'Balance loss, Eyes (vision change), Face drooping, Arm weakness, Speech difficulty, Time to call 911.', source: 'American Heart Association guidelines', status: 'draft' },
  { id: 'fc-adapt-009', cat: 'adapt', front: 'Stroke: before giving clot-busting drugs (alteplase)', back: 'A CT scan to rule out bleeding in the brain, and confirming the client is within the time window.', source: 'American Heart Association guidelines', status: 'draft' },
  { id: 'fc-adapt-010', cat: 'adapt', front: 'Increased intracranial pressure: early sign', back: 'A change in level of consciousness (restlessness, confusion).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-011', cat: 'adapt', front: 'Positioning for increased intracranial pressure', back: 'Head of bed about 30 degrees, head midline, avoid neck and hip flexion.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-012', cat: 'adapt', front: 'Autonomic dysreflexia: cause and first actions', back: 'Spinal cord injury at T6 or above with a trigger such as a full bladder. Sit the client up, find and remove the trigger (check the bladder first), and monitor BP.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-013', cat: 'adapt', front: 'Myocardial infarction: key lab', back: 'Troponin (rises within hours, stays elevated for days).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-014', cat: 'adapt', front: 'Myocardial infarction: early treatment (MONA-B, adjusted)', back: 'Aspirin, nitroglycerin, oxygen if saturation is low, pain relief, and a beta blocker, with rapid reperfusion. Oxygen is no longer routine for everyone.', source: 'American Heart Association guidelines', status: 'draft' },
  { id: 'fc-adapt-015', cat: 'adapt', front: 'Ventricular fibrillation: first action', back: 'Start CPR and defibrillate as soon as possible.', source: 'American Heart Association guidelines', status: 'draft' },
  { id: 'fc-adapt-016', cat: 'adapt', front: 'Adult CPR compression rate and depth', back: '100–120 compressions per minute, at least 2 inches (5 cm) deep, allowing full chest recoil.', source: 'American Heart Association guidelines', status: 'draft' },
  { id: 'fc-adapt-017', cat: 'adapt', front: 'Signs of pulmonary embolism', back: 'Sudden shortness of breath, chest pain, fast heart rate, anxiety and low oxygen saturation.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-018', cat: 'adapt', front: 'Tension pneumothorax signs', back: 'Severe breathing distress, tracheal shift away from the affected side, absent breath sounds on that side, and low BP.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-019', cat: 'adapt', front: 'COPD and oxygen', back: 'Give oxygen to reach the ordered saturation target (often 88–92%). Don\'t withhold oxygen from a client in distress.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-020', cat: 'adapt', front: 'Asthma attack: rescue drug', back: 'A short-acting beta agonist such as albuterol.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-021', cat: 'adapt', front: 'Anaphylaxis: first-line drug', back: 'IM epinephrine, usually in the outer thigh.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-022', cat: 'adapt', front: 'Sepsis: early care bundle', back: 'Blood cultures before antibiotics, lactate level, broad-spectrum antibiotics, and IV fluids for low BP or high lactate.', source: 'Surviving Sepsis Campaign guidelines', status: 'draft' },
  { id: 'fc-adapt-023', cat: 'adapt', front: 'Shock: early vs. late signs', back: 'Early: rising heart rate, restlessness, cool skin. Late: falling BP, very low urine output, confusion.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-024', cat: 'adapt', front: 'Burns: rule of nines (adult)', back: 'Head 9%, each arm 9%, front of trunk 18%, back of trunk 18%, each leg 18%, perineum 1%.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-025', cat: 'adapt', front: 'First priority for a burn victim', back: 'Airway, especially with facial burns, singed nose hairs, soot or hoarseness (inhalation injury).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-026', cat: 'adapt', front: 'Parkland formula for burns', back: '4 mL × weight (kg) × % total body surface area burned, over 24 hours: half in the first 8 hours, the rest over the next 16.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-027', cat: 'adapt', front: 'Acute kidney injury: dangerous electrolyte', back: 'High potassium.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-028', cat: 'adapt', front: 'Hemodialysis access (AV fistula): care', back: 'Feel for a thrill and listen for a bruit. No BP, IVs or blood draws in that arm.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-029', cat: 'adapt', front: 'Signs of hyperthyroidism', back: 'Weight loss, heat intolerance, fast heart rate, nervousness, tremor and bulging eyes (Graves disease).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-030', cat: 'adapt', front: 'Signs of hypothyroidism', back: 'Weight gain, cold intolerance, fatigue, slow heart rate, constipation and dry skin.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-031', cat: 'adapt', front: 'Addisonian crisis signs', back: 'Severe weakness, low BP, low sodium, high potassium and low blood sugar. Treat with IV steroids and fluids.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-032', cat: 'adapt', front: 'Fluid overload signs', back: 'Crackles in the lungs, distended neck veins, edema, weight gain and high BP.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-033', cat: 'adapt', front: 'Appendicitis: concerning sign', back: 'Sudden relief of pain may mean rupture, leading to peritonitis (rigid, board-like abdomen).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-034', cat: 'adapt', front: 'Compartment syndrome: 6 Ps', back: 'Pain (out of proportion), pressure, paresthesia, pallor, paralysis and pulselessness (late).', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
  { id: 'fc-adapt-035', cat: 'adapt', front: 'Signs of a fat embolism after a long-bone fracture', back: 'Confusion, shortness of breath, low oxygen and a petechial rash on the chest, typically 24–72 hours after the injury.', source: 'OpenStax, Medical-Surgical Nursing', status: 'draft' },
];
